  &DefaultButton;




function dir$dmbaohanh(p){
  this.constructor(p);
}
dir$dmbaohanh.prototype = new DirEvent();
dir$dmbaohanh.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmbaohanh.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()
	p.request('request_code_unit', '', '' , function(pp, d, run){
		if (run) {
			p.setDisabled('ma_baohanh', true);
		}
	});
  dir$dmbaohanhDisabledMasterField(p, g);

}

function dir$dmbaohanhDisabledMasterField(p, g){
  if(p.valForm('ma_baohanh').trim() != '') {
    p.setDisabled('ma_baohanh', true);
  }
  else {
    p.setDisabled('ma_baohanh', false);
  }
}






	.control-label.ma_baohanh, .control-label.ten_baohanh
	{	
		//font-weight:bold;	
		color: #499b98;;
	}







DECLARE @ma_unit VARCHAR(32);
SELECT @ma_unit = ma_unit FROM sysunit WHERE unit_id = @@unit;

SELECT @ma_unit + 'BH' + RIGHT('00000' + CAST(ISNULL(MAX(CAST(SUBSTRING(ma_baohanh, LEN(@ma_unit) + 3, 10) AS INT)), 0) + 1 AS VARCHAR), 5) AS [!ma_baohanh]
FROM dmbaohanh
WHERE ma_baohanh LIKE @ma_unit + 'BH%';







if exists(select 1 from @@table a where [%whereFieldKey]) begin
  select '$codeExistsNewMsg' as message, '@@firstFieldKey' as field
  return
end

select @datetime0 = getdate(), @datetime2 = getdate(), @user_id0 = @@userId, @user_id2 = @@userId, @unit_id = @@unit






